 f"Preparation: {read('profile.json')['calls']:,} discarded candidate calls, {read('profile.json')['candidate_seconds']:.2f} candidate seconds, {read('profile.json')['control_calls']:,} intact control calls;1248discarded births/RNG replayed. See software_validation.json and preserved test logs for exact checks and any failed attempts. These are not scientific discoveries.",'',
 f"All{len(read('registration.json')['files'])}registration hashes and396priorM14completion hashes plus19local records verified. Preservation:{p['status']}; storage{p['storage_bytes']/2**20:.2f}MiB;free{p['disk_free_bytes']/2**30:.2f}GiB. Backups: "+', '.join(k+'='+x['backup']['status'] for k,x in p['stages'].items())+'.',
